package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import java.util.HashSet;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class RegisteredDigests {

    private static final Logger logger = LoggerFactory.getLogger(RegisteredDigests.class);

    private final Map<String, String> digestByContainerId = new ConcurrentHashMap<>();

    void register(String containerId, Optional<String> digest) {
        if (digest.isPresent()) {
            logger.debug(
                    "Container {} presented enforcement digest. Adding it to the digests allowlist: it will be used if the enforcement is enabled.",
                    containerId);
            this.digestByContainerId.put(containerId, digest.get());
            EnforcementAudit.digestRegistered(digest.get(), containerId);
        } else {
            logger.debug("Container {} doesn't contain the enforcement digest. "
                    + "If enforcement is enabled, be sure that the digest is included in the Orchestration Service allowlist",
                    containerId);
        }
    }

    boolean unregister(String containerId) {
        String digest = this.digestByContainerId.remove(containerId);
        if (digest == null) {
            return false;
        }
        logger.debug("Removed digest of container with ID {} from Container Instances Allowlist", containerId);
        EnforcementAudit.digestUnregistered(digest, containerId);
        return true;
    }

    Set<String> containerIds() {
        return new HashSet<>(this.digestByContainerId.keySet());
    }

    Set<String> digests() {
        return new HashSet<>(this.digestByContainerId.values());
    }

    Set<String> digestsAllowing(Set<String> imageDigests) {
        return this.digestByContainerId.values().stream().filter(imageDigests::contains).collect(Collectors.toSet());
    }
}
